package com.bank.dlqops.ops;

import com.bank.dlqops.model.Category;
import com.bank.dlqops.model.DeadLetter;

// Root-cause classification from the captured error metadata.
public class FailureClassifier {
    public Category classify(DeadLetter dl) {
        String err = dl.getErrorMessage().toLowerCase();
        if (err.contains("timeout") || err.contains("unavailable") || err.contains("connection")) {
            return Category.TRANSIENT;   // may succeed on replay once dependency recovers
        }
        if (err.contains("deserialize") || err.contains("magic byte") || err.contains("parse")) {
            return Category.POISON;      // needs producer / schema fix
        }
        return Category.PERMANENT;       // validation / business rule -> needs code/data fix
    }
}
