package com.bank.dlqops.ops;

import java.util.logging.*;

// Tracks depth and growth; alerts (pages) when thresholds are crossed.
public class DlqMonitor {
    private static final Logger log = Logger.getLogger(DlqMonitor.class.getName());

    private final int depthThreshold;
    private final int growthThreshold; // new records in a window
    private int depth = 0;

    public DlqMonitor(int depthThreshold, int growthThreshold) {
        this.depthThreshold = depthThreshold;
        this.growthThreshold = growthThreshold;
    }

    // Record a window of arrivals and evaluate alerts.
    public boolean ingestWindow(int arrivals) {
        depth += arrivals;
        boolean alert = false;
        if (arrivals >= growthThreshold) {
            log.severe("ALERT: DLT grew by " + arrivals + " in window (>= " + growthThreshold
                + ") — likely incident (dependency down or bad producer).");
            alert = true;
        }
        if (depth >= depthThreshold) {
            log.severe("ALERT: DLT depth=" + depth + " (>= " + depthThreshold
                + ") — backlog must be drained.");
            alert = true;
        }
        if (!alert) log.info(() -> "DLT healthy: depth=" + depth + ", window arrivals=" + arrivals);
        return alert;
    }

    public int getDepth() { return depth; }
}
