package com.bank.dlqops.ops;

import com.bank.dlqops.model.Category;
import java.util.EnumMap;
import java.util.Map;

// Clear ownership: each failure category has a responsible team.
public class OwnershipRegistry {
    private final Map<Category, String> owners = new EnumMap<>(Category.class);

    public OwnershipRegistry() {
        owners.put(Category.TRANSIENT, "Settlement Platform (replay after recovery)");
        owners.put(Category.PERMANENT, "Settlement Dev (fix validation/data)");
        owners.put(Category.POISON, "Producing Team + Schema Governance");
    }
    public String ownerFor(Category c) { return owners.get(c); }
}
