package com.bank.dlqops;

import com.bank.dlqops.model.Category;
import com.bank.dlqops.model.DeadLetter;
import com.bank.dlqops.ops.*;
import java.util.*;
import java.util.logging.*;

public class DlqOpsDemo {
    private static final Logger log = Logger.getLogger(DlqOpsDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FailureClassifier classifier = new FailureClassifier();
        DlqMonitor monitor = new DlqMonitor(100, 50);
        OwnershipRegistry registry = new OwnershipRegistry();

        List<DeadLetter> burst = new ArrayList<>();
        for (int i = 0; i < 40; i++) burst.add(new DeadLetter("TRD-T" + i, "credit bureau timeout"));
        for (int i = 0; i < 15; i++) burst.add(new DeadLetter("TRD-P" + i, "validation: amount negative"));
        for (int i = 0; i < 5; i++) burst.add(new DeadLetter("TRD-X" + i, "deserialize: unknown magic byte"));

        // Step 1: monitor the burst -> alert fires
        boolean alerted = monitor.ingestWindow(burst.size());
        log.info("Alert fired? " + alerted + " (depth=" + monitor.getDepth() + ")");

        // Step 2: classify and attribute ownership
        Map<Category, Integer> counts = new EnumMap<>(Category.class);
        for (DeadLetter dl : burst) {
            Category c = classifier.classify(dl);
            counts.merge(c, 1, Integer::sum);
        }
        counts.forEach((c, n) -> log.warning(c + " = " + n + " -> owner: " + registry.ownerFor(c)));

        log.info("DLQ treated as INCIDENT: alerted, classified, owners notified, redrive next.");
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
